window.SITE_DATA = {"updated": "2026-10-26", "name": {"zh": "杨龙箴", "en": "Longzhen Yang"}, "email": "yanglongzhen@tongji.edu.cn", "github": "https://github.com/kaelsunkiller", "scholar": "https://scholar.google.com/citations?user=mZjfCT8AAAAJ", "tagline": {"zh": "可信医学视觉语言学习与临床智能", "en": "Reliable medical vision-language learning and clinical intelligence"}, "bio": {"zh": ["我在同济大学计算机科学与技术学院攻读博士，师从何良华教授。我的研究关注医学影像与语言之间的可靠联系：让模型生成的内容有视觉证据，让学到的表征能够跨任务与跨数据泛化，并在真实临床场景中得到验证。", "博士论文《面向临床的医学影像报告生成》围绕报告可靠性、模型泛化性与临床适用性，形成从变分生成、自监督解剖对齐、生成式预训练与多病灶合成，到眼底多系统疾病筛查的连续研究路径。", "我优先寻求产业研究与算法研发机会，也关注高校科研岗位，希望与多模态学习、可信生成模型及医工交叉领域的研究者合作。"], "en": ["I am a doctoral researcher in Computer Science and Technology at Tongji University, advised by Prof. Lianghua He. My research connects medical images and language through visual evidence, transferable representations, and validation in real clinical settings.", "My dissertation, Clinically Oriented Medical Image Report Generation, studies report reliability, model generalization, and clinical applicability. It connects variational generation, self-supervised anatomical alignment, generative pretraining, multi-lesion synthesis, and retinal screening for multisystem diseases.", "I am primarily seeking industry research and algorithm development opportunities, while also considering academic research positions. I welcome collaborations in multimodal learning, trustworthy generative models, and clinical AI."]}, "interests": {"zh": ["医学视觉语言模型", "自监督与可解释表征", "多样化与可控生成", "临床人工智能与科学智能"], "en": ["Medical vision-language models", "Self-supervised and interpretable representations", "Diverse and controllable generation", "Clinical AI and AI for Science"]}, "education": [{"name": {"zh": "同济大学", "en": "Tongji University"}, "degree": {"zh": "计算机科学与技术 · 博士研究生", "en": "Ph.D. research, Computer Science and Technology"}, "date": "2021–2026", "detail": {"zh": "导师：何良华教授。", "en": "Advisor: Prof. Lianghua He."}}, {"name": {"zh": "江西财经大学", "en": "Jiangxi University of Finance and Economics"}, "degree": {"zh": "计算机科学与技术 · 硕士", "en": "M.S., Computer Science and Technology"}, "date": "2018–2021", "detail": {"zh": "江西省优秀毕业生、校优秀研究生。", "en": "Outstanding Graduate of Jiangxi Province; university Outstanding Graduate Student."}}, {"name": {"zh": "合肥工业大学", "en": "Hefei University of Technology"}, "degree": {"zh": "计算机科学与技术 · 学士", "en": "B.Eng., Computer Science and Technology"}, "date": "2011–2015", "detail": {"zh": "", "en": ""}}], "skills": [{"zh": ["研究方法", "Transformer、ViT、VAE、混合专家、对比学习、扩散模型与流匹配。"], "en": ["Modeling", "Transformers, ViT, VAE, mixture of experts, contrastive learning, diffusion, and flow matching."]}, {"zh": ["训练与评测", "Python / PyTorch；多 GPU、混合精度、训练管线，以及分类、定位、分割、检索和报告生成评测。"], "en": ["Training and evaluation", "Python / PyTorch; multi-GPU training, mixed precision, and evaluation of classification, grounding, segmentation, retrieval, and report generation."]}, {"zh": ["系统与交付", "Linux、Git、Docker；Flask / FastAPI / Gradio，模型服务、前后端接口与部署联调。"], "en": ["Systems and delivery", "Linux, Git, Docker; Flask / FastAPI / Gradio, model services, frontend/backend integration, and deployment troubleshooting."]}], "service": {"zh": "为 ACM MM、AAAI、IEEE TCSVT、IEEE TNNLS、IEEE JBHI 等会议与期刊提供同行评审，并担任 IEEE SMC 2026 审稿人。", "en": "Reviewer for venues including ACM MM, AAAI, IEEE TCSVT, IEEE TNNLS, and IEEE JBHI; reviewer for IEEE SMC 2026."}, "projects_grants": [{"zh": ["国家重点研发计划", "新型信息服务的表征与适配机制（2020YFA0711402）。参与技术研究、季度报告、结题报告和跨单位材料整合。"], "en": ["National Key R&D Program", "Representation and adaptation mechanisms for new information services (2020YFA0711402). Contributed to research, technical reporting, and coordination across institutions."]}, {"zh": ["上海市眼科筛查大模型项目", "眼科筛查大模型构建及在社区健康筛查中的应用（25JS2840101）。参与模型方案、数据库构建及临床应用协作。"], "en": ["Shanghai retinal screening project", "Foundation models for ophthalmic and community health screening (25JS2840101). Contributed to modeling, database construction, and clinical collaboration."]}, {"zh": ["心肾代谢慢病科学智能体研究", "参与眼部标志物研究方案、模型训练和大规模筛查数据库建设，连接眼科影像与跨系统疾病分析。"], "en": ["Scientific AI agents for CKM health", "Contributed to ocular-biomarker research design, model training, and a large-scale screening database connecting retinal images to multisystem disease analysis."]}], "personal": {"zh": "研究之外，我喜欢游泳与运动。规律训练让我在长周期研究之外保持节奏，也让我持续关注身体、健康与日常生活之间的联系。", "en": "Outside research, I enjoy swimming and exercise. Regular training provides a rhythm alongside long research projects and keeps me interested in the connection between health and everyday life."}, "outlook": {"zh": "下一阶段，我希望围绕视觉证据一致性、生成置信度校准、跨中心泛化和多模态临床信息整合继续研究。在方法层面连接表征学习与生成建模，在验证层面重视外部队列、失败分析与前瞻性应用研究。", "en": "My next research directions include visual-evidence consistency, calibrated generation, cross-center generalization, and multimodal clinical integration. I aim to connect representation learning with generative modeling and strengthen validation through external cohorts, failure analysis, and prospective studies."}, "research": [{"id": "ssacl", "name": {"zh": "SS-ACL：自监督解剖一致性学习", "en": "SS-ACL: self-supervised anatomical consistency"}, "category": "reliability", "status": {"zh": "ACM MM 2025 · 最佳论文候选", "en": "ACM MM 2025 · Best Paper Candidate"}, "role": {"zh": "第一作者", "en": "First author"}, "summary": {"zh": "在无需区域标注和外部检测器的条件下，将医学报告中的描述连接到对应的解剖区域。", "en": "Link report descriptions to anatomical regions without regional annotations or an external detector."}, "problem": {"zh": "医学报告语言流畅，并不意味着描述有视觉证据。依赖专家框标注的两阶段方法还带来标注成本与跨数据偏差。", "en": "Fluent medical reports do not necessarily provide visual evidence. Two-stage systems relying on expert boxes introduce annotation costs and distribution bias."}, "method": {"zh": "构建 4 层、32 节点的层级解剖图，通过局部与全局重建学习空间表征；结合跨样本解剖一致性对比，将对齐表征引入报告生成。", "en": "Construct a four-level, 32-node anatomical graph. Learn spatial representations through local/global reconstruction and cross-sample anatomical contrast, then guide report generation using the aligned representations."}, "contribution": {"zh": "负责问题定义、方法设计、核心模型实现、训练与评测、结果分析及论文撰写；构建 ViT、BERT 与 GPT-2 的联合训练流程。", "en": "Led problem formulation, method design, core implementation, training, evaluation, analysis, and writing; built the joint ViT, BERT, and GPT-2 training pipeline."}, "evidence": {"zh": "原论文报告：词汇准确性相对提升约 10%，临床有效性约 25%，零样本视觉定位约 8%。预训练使用约 22.3 万张 MIMIC-CXR 训练图像，并验证多个下游任务。各数值对应论文各自的任务与对比设置。", "en": "The paper reports approximately 10% relative improvement in lexical accuracy, 25% in clinical efficacy, and 8% in zero-shot visual grounding. Pretraining uses about 223K MIMIC-CXR training images, with evaluation across multiple downstream tasks. Gains refer to their respective comparison settings."}, "figures": [{"file": "ssacl_method.png", "caption": {"zh": "层级解剖重建、跨样本一致性对齐与解剖引导生成。", "en": "Hierarchical reconstruction, anatomical consistency alignment, and anatomy-guided generation."}}, {"file": "ssacl_teaser.png", "caption": {"zh": "从专家标注依赖到自监督视觉证据对齐。", "en": "From expert-annotation dependence to self-supervised visual grounding."}}], "links": [{"label": {"zh": "论文", "en": "Paper"}, "url": "https://doi.org/10.1145/3746027.3754913"}, {"label": {"zh": "开源代码", "en": "Code"}, "url": "https://github.com/kaelsunkiller/ssacl"}], "authors": "Longzhen Yang, Zhangkai Ni, Ying Wen, Yihang Liu, Lianghua He, Heng Tao Shen", "title": {"zh": "自监督解剖一致性学习驱动的视觉证据医学报告生成", "en": "Self-Supervised Anatomical Consistency Learning for Vision-Grounded Medical Report Generation"}}, {"id": "vat", "name": {"zh": "VaT：准确性与多样性兼顾的生成", "en": "VaT: accurate and diverse generation"}, "category": "reliability", "status": {"zh": "IEEE TNNLS 2025", "en": "IEEE TNNLS 2025"}, "role": {"zh": "第一作者", "en": "First author"}, "summary": {"zh": "研究视觉描述中准确性与多样性的协同，为可靠的多候选语义生成建立基础。", "en": "Study accuracy and diversity together, building a foundation for reliable generation of multiple semantic candidates."}, "problem": {"zh": "单一参考式优化容易压缩生成空间；单独追求多样性又可能降低图像与描述之间的语义一致性。", "en": "Reference-driven optimization can collapse the generation space, while diversity alone may weaken image-caption semantic consistency."}, "method": {"zh": "在 Transformer 中引入隐式信息先验、自选择高斯混合先验与范围中位数奖励，学习多种合理语义并保留高质量候选。", "en": "Introduce an invisible-information prior, an auto-selectable Gaussian mixture model, and a range-median reward to represent multiple valid semantics and preserve high-quality candidates."}, "contribution": {"zh": "负责方法设计、变分生成模型实现、强化学习奖励设计、实验与论文写作。使用 2 张 RTX 3090 开展模型训练。", "en": "Led method design, variational implementation, reinforcement-learning reward design, experiments, and writing. Trained the model using two RTX 3090 GPUs."}, "evidence": {"zh": "论文语义检索得分为 50.3，人工标注参考为 50.6；实验同时考察准确性、多样性与人工评价。该指标用于语义检索，不等同于临床诊断性能。", "en": "Semantic retrieval reaches 50.3 compared with 50.6 for human annotations. Evaluation considers accuracy, diversity, and human assessment. This is a retrieval metric, not clinical diagnostic performance."}, "figures": [{"file": "vat-paper-figure.png", "caption": {"zh": "原论文图示：准确性、多样性与语义关联。", "en": "Original paper excerpt: accuracy, diversity, and semantic correspondence."}}], "links": [{"label": {"zh": "论文", "en": "Paper"}, "url": "https://doi.org/10.1109/TNNLS.2024.3440872"}], "authors": "Longzhen Yang, Lianghua He, Die Hu, Yihang Liu, Yitao Peng, Hongzhou Chen, MengChu Zhou", "title": {"zh": "变分 Transformer：超越图像描述准确性与多样性的权衡", "en": "Variational Transformer: A Framework Beyond the Tradeoff Between Accuracy and Diversity for Image Captioning"}}, {"id": "gmvlp", "name": {"zh": "GM-VLP：生成式医学视觉语言预训练", "en": "GM-VLP: generative medical vision-language pretraining"}, "category": "generalization", "status": {"zh": "IEEE TMM · 审稿中", "en": "IEEE TMM · Under review"}, "role": {"zh": "第一作者", "en": "First author"}, "summary": {"zh": "在报告生成之外保留可迁移的医学视觉表征，连接分类、分割、检索与定位。", "en": "Preserve transferable medical visual representations alongside report generation, connecting classification, segmentation, retrieval, and grounding."}, "problem": {"zh": "逐词生成的语言目标可能让视觉表征过度适应报告任务，削弱对局部病理信息与其他任务的支持。", "en": "Token-level generation objectives may over-specialize visual representations for reports and weaken local pathology information and transfer."}, "method": {"zh": "以短语检索生成减少表层语言噪声，结合提示引导的局部视觉表征配对和多粒度互信息学习，增强生成与判别任务之间的共享表征。", "en": "Combine phrase-retrieval generation, prompt-guided local visual pairing, and multi-granularity mutual-information learning to connect generative and discriminative representations."}, "contribution": {"zh": "负责预训练框架、数据与检索管线、训练调试、多任务评测和论文撰写；将研究延伸为短语级知识检索增强流程。", "en": "Led the pretraining framework, data/retrieval pipelines, training, multi-task evaluation, and writing; extended the approach toward phrase-level knowledge retrieval."}, "evidence": {"zh": "博士论文报告：微调报告生成的语言、临床有效性和图结构与向量三组指标分别平均提升约 11%、14% 和 37%。这些是指标组平均增益，不能替代逐项任务结果。", "en": "The dissertation reports average gains of approximately 11%, 14%, and 37% for language, clinical-efficacy, and graph/vector metric groups in fine-tuned report generation. These grouped gains should be read with the individual task evaluations."}, "figures": [{"file": "gen_pretrain_mi.png", "caption": {"zh": "多粒度互信息与生成式预训练方法图。", "en": "Multi-granularity mutual information and generative pretraining."}}, {"file": "gen_pretrain_results.png", "caption": {"zh": "报告生成与下游任务的实验结果。", "en": "Report-generation and downstream evaluation results."}}], "links": [], "authors": "", "title": {"zh": "GM-VLP：生成式医学视觉语言预训练", "en": "GM-VLP: generative medical vision-language pretraining"}}, {"id": "snot", "name": {"zh": "SNOT：多病灶可控生成与编辑", "en": "SNOT: controllable multi-lesion generation"}, "category": "generalization", "status": {"zh": "拟投稿 CVPR 2027 · 稿件准备中", "en": "Preparing for CVPR 2027 submission"}, "role": {"zh": "第一作者", "en": "First author"}, "summary": {"zh": "以链式非最优传输缓解多病灶条件生成的实例竞争，提高复杂病例合成与数据增强的质量。", "en": "Use sequential non-optimal transport to reduce instance competition in multi-lesion synthesis and improve complex-case augmentation."}, "problem": {"zh": "多个疾病条件可能在生成过程中相互竞争，造成病灶遗漏、位置偏移或非编辑区域结构变化。", "en": "Multiple pathology conditions can compete during synthesis, causing missing findings, spatial drift, or changes outside edited regions."}, "method": {"zh": "分析联合生成的传输偏置，将轨迹分解为可累积的局部链式路径，通过局部速度估计协调多个病灶的生成。", "en": "Analyze transport bias in joint generation, decompose trajectories into accumulable local chains, and coordinate lesions through local velocity estimation."}, "contribution": {"zh": "负责方法建模、生成与编辑实现、基线对比、下游报告生成与分类实验，以及 Gradio、Flask 与网关式演示部署。", "en": "Led formulation, generation/editing implementation, baseline comparisons, downstream report/classification experiments, and a Gradio/Flask/gateway demonstration workflow."}, "evidence": {"zh": "现有多病灶编辑实验取得 FID 23.01（FlowEdit 32.64）；合成数据分类 mAP 为 0.301，真实数据参考为 0.302。视频展示生成、分割、热图、框与基线比较；这些结果属于准备投稿阶段。", "en": "Current multi-lesion editing experiments achieve FID 23.01 versus 32.64 for FlowEdit, and classification mAP 0.301 with synthetic data versus 0.302 for the real-data reference. The recording shows generation, segmentation, heatmaps, boxes, and baselines. Results remain part of a manuscript in preparation."}, "figures": [{"file": "snot_method.png", "caption": {"zh": "链式传输与局部速度估计。", "en": "Sequential transport and local velocity estimation."}}, {"file": "snot_results.png", "caption": {"zh": "多病灶生成与不同基线的真实结果对比。", "en": "Original multi-lesion generation comparisons with baselines."}}, {"file": "snot_qualitative.png", "caption": {"zh": "条件生成与编辑的定性案例。", "en": "Qualitative conditional-generation and editing cases."}}], "links": [], "authors": "", "title": {"zh": "SNOT：多病灶可控生成与编辑", "en": "SNOT: controllable multi-lesion generation"}}, {"id": "sfm", "name": {"zh": "SFM：眼底多系统疾病筛查基础模型", "en": "SFM: a retinal screening foundation model"}, "category": "clinical", "status": {"zh": "Nature Communications · 审稿中", "en": "Nature Communications · Under review"}, "role": {"zh": "第一作者", "en": "First author"}, "summary": {"zh": "用常规眼底照片连接眼科疾病与心肾代谢健康，研究筛查、风险分层和综合健康报告。", "en": "Connect routine retinal photographs to ophthalmic and cardio-kidney-metabolic health, studying screening, risk stratification, and health reporting."}, "problem": {"zh": "系统性疾病需要跨科室综合信息；模型不仅需要内部测试表现，还要经受跨人群、跨设备和真实队列检验。", "en": "Systemic diseases require integrated information across specialties; models must be examined across populations, devices, and real cohorts beyond internal benchmarks."}, "method": {"zh": "基于 212,610 张眼底影像开展预训练，使用混合专家编码器学习共享与疾病特异性表征，并对齐结构化健康记录形成的临床文本。", "en": "Pretrain on 212,610 retinal photographs using a mixture-of-experts encoder for shared and disease-specific representations, aligned with clinical text derived from structured health records."}, "contribution": {"zh": "主导模型方案、数据管线、训练评测与论文工作，并对接医院和企业，推进 Docker 环境、模型服务和系统接口联调。", "en": "Led modeling, data pipelines, training/evaluation, and manuscript work; collaborated with hospital and industry teams on Docker environments, model services, and system interfaces."}, "evidence": {"zh": "博士论文中 SFM-M2 在 8 个眼科基准上的平均 AUROC 为 0.914，在 6 类 CKM 共病上的平均 AUROC 为 0.822。稿件包含 6,931 张外部影像的分期评估、纵向分析与卫生经济学研究；社区系统经历见独立演示。", "en": "The dissertation reports mean AUROC 0.914 across eight ophthalmic benchmarks and 0.822 across six CKM comorbidities for SFM-M2. The manuscript includes staging evaluation on 6,931 external images, longitudinal analysis, and health-economic assessment. See the separate community-system demonstration."}, "figures": [{"file": "sfm-pipeline.png", "caption": {"zh": "从临床感知预训练到内部、外部与真实世界验证。", "en": "From clinically informed pretraining to internal, external, and real-world evaluation."}}, {"file": "sfm_performance.png", "caption": {"zh": "眼科任务与心肾代谢共病的基准结果。", "en": "Benchmark results for ophthalmic tasks and CKM comorbidities."}}, {"file": "sfm_stage.png", "caption": {"zh": "跨队列分期与风险分析。", "en": "Cross-cohort staging and risk analysis."}}], "links": [{"label": {"zh": "开源代码", "en": "Code"}, "url": "https://github.com/kaelsunkiller/SFM"}], "authors": "", "title": {"zh": "基于常规眼底照片的心肾代谢健康筛查基础模型", "en": "A Screening Foundation Model for Cardio–Kidney–Metabolic Health using Routine Retinal Photographs"}}, {"id": "midol", "name": {"zh": "M-IDoL：多模态信息分解", "en": "M-IDoL: multimodal information decomposition"}, "category": "foundation", "status": {"zh": "ICML 2026", "en": "ICML 2026"}, "role": {"zh": "通讯作者", "en": "Corresponding author"}, "summary": {"zh": "面向统一医学基础模型，分解模态特异性与细粒度信息，降低不同医学模态之间的表征干扰。", "en": "Decompose modality-specific and fine-grained information in unified medical foundation models, reducing interference between medical modalities."}, "problem": {"zh": "统一多模态预训练可能混合模态间差异，削弱对各类医学图像特有信息的建模。", "en": "Unified pretraining may mix modality differences and weaken the modeling of information specific to each medical image type."}, "method": {"zh": "通过信息分解目标与混合专家表征子空间，兼顾跨模态特异性和模态内多样化信息。", "en": "Use information-decomposition objectives and mixture-of-experts representation subspaces to preserve cross-modality specificity and within-modality diversity."}, "contribution": {"zh": "参与研究方案讨论、方法完善、实验分析与论文指导，承担通讯作者工作。", "en": "Contributed to research design, method refinement, experimental analysis, and manuscript supervision as a corresponding author."}, "evidence": {"zh": "在约 115 万张医学图像、5 类影像模态上开展预训练，并在 21 项临床任务中与 20 个基础模型比较。", "en": "Pretraining uses approximately 1.15M medical images across five modalities and evaluation on 21 clinical tasks against 20 foundation models."}, "figures": [], "links": [{"label": {"zh": "论文", "en": "Paper"}, "url": "https://openreview.net/forum?id=pn5lQVm3DH"}], "authors": "Yihang Liu, Longzhen Yang, Jiaxiong Yang, Ying Wen, Lianghua He, Heng Tao Shen", "title": {"zh": "医学基础模型中模态特异性与多样化表征学习的信息分解", "en": "M-IDoL: Information Decomposition for Modality-Specific and Diverse Representation Learning in Medical Foundation Model"}}, {"id": "radlas", "name": {"zh": "RadLAS：病灶感知可解释预训练", "en": "RadLAS: lesion-aware interpretable pretraining"}, "category": "foundation", "status": {"zh": "ACM MM 2025 · 杰出论文奖", "en": "ACM MM 2025 · Outstanding Paper Award"}, "role": {"zh": "通讯作者", "en": "Corresponding author"}, "summary": {"zh": "结合病灶感知自监督预训练与可解释评测，探索影像基础模型的定位和解释能力。", "en": "Combine lesion-aware self-supervised pretraining with interpretable evaluation to study localization and explanation in radiography foundation models."}, "problem": {"zh": "单纯全局图像表征可能忽略局部病灶，限制基础模型的视觉证据与可解释性。", "en": "Global representations can overlook local lesions, limiting visual evidence and interpretability."}, "method": {"zh": "通过病灶感知预训练，联合考虑图像表征、局部病理与下游分类、定位和解释任务。", "en": "Connect image representations and local pathology through lesion-aware pretraining and downstream classification, localization, and explanation tasks."}, "contribution": {"zh": "参与研究方案设计、实验分析、论文修改与研究指导，承担通讯作者工作。", "en": "Contributed to research design, experimental analysis, manuscript revision, and research supervision as a corresponding author."}, "evidence": {"zh": "论文获 ACM MM 2025 Outstanding Paper Award。作品集保留原论文页面作为方法依据，并与 SS-ACL 的视觉证据研究形成互补。", "en": "The work received an ACM MM 2025 Outstanding Paper Award. Original paper excerpts document the method, complementing the visual-evidence research in SS-ACL."}, "figures": [{"file": "radlas-method.png", "caption": {"zh": "RadLAS 原论文方法页面节选。", "en": "Excerpt from the original RadLAS method page."}}], "links": [], "authors": "Yihang Liu, Ying Wen, Longzhen Yang, Lianghua He, Heng Tao Shen", "title": {"zh": "基于病灶感知自监督预训练的可解释胸片分析基础模型", "en": "RadLAS: A Foundation Model for Interpretable Radiography Image Analysis with Lesion-Aware Self-Supervised Pre-training"}}, {"id": "xmid", "name": {"zh": "可解释医学影像的可视化方法综述", "en": "Visualization for explainable medical imaging"}, "category": "reliability", "status": {"zh": "Computer Science Review 2026", "en": "Computer Science Review 2026"}, "role": {"zh": "第一作者", "en": "First author"}, "summary": {"zh": "系统整理解释模态、医学任务、可视化方法与评测方式，为可信医学模型提供研究框架。", "en": "Organize explanation modalities, medical tasks, visualization methods, and evaluation to support trustworthy medical modeling."}, "problem": {"zh": "解释图的直观性并不等于忠实性；不同医学任务需要不同解释粒度与评价标准。", "en": "An intuitive explanation is not necessarily faithful; different medical tasks require distinct granularities and evaluation criteria."}, "method": {"zh": "围绕视觉、文本、示例与概念解释，连接分类、检测、分割、生成和推理任务，并讨论数据集、质量评估与临床适用性。", "en": "Connect visual, textual, example-based, and concept-based explanations to classification, detection, segmentation, generation, and reasoning, including datasets and evaluation."}, "contribution": {"zh": "负责文献梳理、分类框架、可视化组织、讨论与综述撰写。", "en": "Led literature synthesis, the taxonomy, visual organization, discussion, and survey writing."}, "evidence": {"zh": "发表于 Computer Science Review，第 61 卷，文章号 100930。综述为后续证据对齐与可靠性研究提供方法背景。", "en": "Published in Computer Science Review, volume 61, article 100930. The survey provides methodological context for evidence alignment and reliability research."}, "figures": [{"file": "xmid-survey-figure.png", "caption": {"zh": "原综述图示：可解释医学影像研究框架。", "en": "Original survey excerpt: a framework for explainable medical imaging."}}], "links": [{"label": {"zh": "论文", "en": "Paper"}, "url": "https://doi.org/10.1016/j.cosrev.2026.100930"}], "authors": "Longzhen Yang, Yihang Liu, Lianghua He, Die Hu", "title": {"zh": "可解释医学影像诊断的可视化方法综述", "en": "Visualization methods for explainable medical imaging diagnosis: A survey"}}], "demos": [{"id": "snot-demo", "name": {"zh": "SNOT：胸片生成与编辑工作台", "en": "SNOT: radiograph generation and editing"}, "summary": {"zh": "录屏展示从病灶条件输入到生成、分割、热图、边界框和基线对比的完整工作流。", "en": "Recording of the workflow from pathology conditions to synthesis, segmentation, heatmaps, bounding boxes, and baseline comparisons."}, "detail": {"zh": "系统包含 Gradio 页面、模型封装、Flask 后端和网关。将病灶提示、生成结果、定位证据与基线比较整合为可浏览的研究工作流。", "en": "The system includes a Gradio interface, model wrappers, a Flask backend, and a gateway. The workstation brings pathology prompts, generated images, localization evidence, and baseline comparisons into one research workflow."}, "cover": "snot-video-poster.jpg", "video": "snot-demo-web.mp4", "mode": {"zh": "模型演示录屏", "en": "Recorded model demonstration"}, "gallery": []}, {"id": "visionscope", "name": {"zh": "VisionScope：图像描述智能体", "en": "VisionScope: an image-description agent"}, "summary": {"zh": "动态展示视觉读取、目标定位、局部描述、关系推理与全局描述；本视频记录本地 Qwen3-VL 的真实 GPU 推理。", "en": "Follow visual reading, object grounding, local description, relation reasoning, and global description. This recording captures real local GPU inference with Qwen3-VL."}, "detail": {"zh": "采用 React 前端与 FastAPI 后端，支持真实推理与缓存演示两种模式。保留两类录屏并明确标注，便于理解模型工作流与演示交互。", "en": "Built with React and FastAPI, supporting real inference and a cached demonstration mode. The recordings are labeled separately to clarify both model behavior and the presentation workflow."}, "cover": "visionscope-02-analysis-complete.png", "video": "visionscope-gpu-demo.mp4", "mode": {"zh": "真实 GPU 推理录屏", "en": "Recorded real GPU inference"}, "gallery": ["visionscope-01-home.png", "visionscope-03-local-gpu-random-upload.png"]}, {"id": "community", "name": {"zh": "明眸：眼观全身社区健康筛查工作站", "en": "Mingmou: a community health-screening workstation"}, "summary": {"zh": "以眼底多图筛查连接心肾代谢风险、糖网分级、关注区域、综合报告、医生复核与随访。", "en": "Connect multi-image retinal screening to CKM risk, diabetic-retinopathy grading, attention maps, health reports, clinician review, and follow-up."}, "detail": {"zh": "包含 Vue 前端、Flask 后端与模型工作进程，体现研究模型向临床工作流的系统化交付。以下截图来自已提供的虚拟展示版本，病例与报告为虚拟数据。", "en": "A Vue frontend, Flask backend, and model worker illustrate delivery from research models to a clinical workflow. The interface screenshots present virtual cases and reports for demonstration."}, "cover": "crc_community-virtual-overview.png", "mode": {"zh": "虚拟病例界面展示", "en": "Interface demonstration with virtual cases"}, "gallery": ["crc_community-virtual-report.png", "crc_community-virtual-mobile.png"]}], "journal": {"title": {"zh": "把大家从实验室约到球场", "en": "A little time on court"}, "subtitle": {"zh": "学院研究生羽毛球赛的一点小记", "en": "A note on organizing our graduate badminton tournament"}, "excerpt": {"zh": "组织过学院研究生羽毛球比赛。希望比赛之外，大家还能多认识几位同学，多一个走出实验室的理由。", "en": "I organized a graduate badminton tournament for our school—a chance to step away from the lab, meet fellow students, and enjoy a little time on court."}, "photo": "badminton-tournament.jpg", "caption": {"zh": "学院研究生羽毛球比赛合影。", "en": "A photograph from our graduate badminton tournament."}, "paragraphs": {"zh": ["组织学院研究生羽毛球赛时，我想得很简单：让大家有个理由关上电脑，出出汗，认识几位其他实验室的同学。", "我在意的是些小事：报名清楚一点，规则简单一点，赛程留一点余量。希望常打球的人能认真过招，偶尔打球的人也能轻松参与。", "再看这张合影，比分反而没那么重要了。要是有人因此多认识了一位球友，下次想运动时多了一个可以约的人，我就觉得很值得。"], "en": ["I organized our school’s graduate badminton tournament with a simple hope: give everyone a reason to close the laptop, move around, and meet someone from another lab.", "I cared about the small things: clear sign-ups, simple rules, and a schedule with a little breathing room. Regular players should enjoy a proper match; occasional players should feel just as welcome.", "Looking at this photograph, the score matters less than having everyone together. If someone left with a new badminton partner, or one more person to call for a game, that feels like something worth organizing."]}}, "liveTalk": {"title": {"zh": "ACM MM 现场报告", "en": "ACM Multimedia: on-site presentation"}, "file": "acmmm2025-live-presentation.mp4", "poster": "acmmm2025-live-poster.jpg"}};
